    te = cfg["time_edges"]; chk(isinstance(te,list) and 1<=len(te)<=16)
    chk(all(ok_int(x,0,10**12) for x in te) and te[0]==0 and all(te[i]<te[i+1] for i in range(len(te)-1)))
    ce = cfg["count_edges"]; chk(isinstance(ce,list) and 1<=len(ce)<=16)
    chk(all(ok_int(x,0,20000) for x in ce) and ce[0]==0 and all(ce[i]<ce[i+1] for i in range(len(ce)-1)))
    pr = cfg["probability"]; chk(isinstance(pr,len(te)*[0]) and len(pr)==len(te))
    for r in pr: chk(isinstance(r,list) and len(r)==len(ce) and all(ok_int(x,0,65536) for x in r))
    LE = mdl["length_embedding"]; chk(isinstance(LE,list) and len(LE)==16)
    for r in LE: chk(isinstance(r,list) and len(r)==E and all(ok_int(x,-128,127) for x in r))
    GE = mdl["gap_embedding"]; chk(isinstance(GE,list) and len(GE)==16)
    for r in GE: chk(isinstance(r,list) and len(r)==E and all(ok_int(x,-128,127) for x in r))
    K = mdl["kernel"]; chk(ok_int(K,1,5) and K<=W)
    cw = mdl["conv_weights"]; chk(isinstance(cw,list) and 1<=len(cw)<=8)
    for frow in cw:
        chk(isinstance(frow,list) and len(frow)==K)
        for krow in frow:
            chk(isinstance(krow,list) and len(krow)==2*E and all(ok_int(x,-128,127) for x in krow))
    cb = mdl["conv_bias"]; chk(isinstance(cb,list) and len(cb)==len(cw) and all(ok_int(x,-2**31,2**31-1) for x in cb))
    cs = mdl["conv_shift"]; chk(isinstance(cs,list) and len(cs)==len(cw) and all(ok_int(x,0,16) for x in cs))
    dw = mdl["dense_weights"]; chk(isinstance(dw,list) and len(dw)==C)
    for r in dw: chk(isinstance(r,list) and len(r)==len(cw) and all(ok_int(x,-128,127) for x in r))
    db = mdl["dense_bias"]; chk(isinstance(db,list) and len(db)==C and all(ok_int(x,-2**31,2**31-1) for x in db))
    F = len(cw)
    conns = doc["connections"]; chk(isinstance(conns,list) and len(conns)<=2048)
    ids=[]; slot={}; label={}; split={}
    for c in conns:
