    def requant(z, sh):
        if sh == 0: return z
        # round half away from zero
        if z >= 0:
            q = (2*z + (1<<sh)) // (2<<sh)
        else:
            q = -((-2*z + (1<<sh)) // (2<<sh))
        return q
    def cnn(window):
        x = []
        for (a,b) in window:
            x.append(LE[a] + GE[b])
        pooled=[]
        for f in range(F):
            vals=[]
            for j in range(0, W-K+1):
                z = cb[f]
                for k in range(K):
                    for d in range(2*E):
                        z += cw[f][k][d]*x[j+k][d]
                q = requant(z, cs[f])
                q = max(0, min(127, q))
                vals.append(q)
            pooled.append(max(vals))
        logits=[db[c] + sum(dw[c][f]*pooled[f] for f in range(F)) for c in range(C)]
        mx = max(logits)
        return logits, logits.index(mx)

    def finish_jobs(t):
        nonlocal pend
        ready = sorted([j for j in pend if pend[j]["done"] <= t], key=lambda j:(pend[j]["done"], j))
        for j in ready:
            job = pend.pop(j)
            s = job["slot"]
            if occ[s] is None or occ[s] != job["connection"] or gen[s] != job["generation"]:
                job["status"]="stale"
            elif j <= lastap[s]:
                job["status"]="superseded"
            else:
                job["status"]="applied"
                cls[s]=job["prediction"]; lastap[s]=j
            oj.append(job)

    for i,p in enumerate(pkts):
